// T504b: the entity source pruning regression net.
//
// Runs tools/hwcaps/model_fingerprint (headless, production RaceModelLoader)
// for each audit zone and diffs its output against the golden generated by
// the pre-pruning code (tests/goldens/model_fingerprint/<zone>.txt). The
// unit's claim is BYTE-IDENTICAL model data, so any diff is a failure. Skips
// when the EQ client tree or the shipped db is absent (like the other asset
// tests).
#include <gtest/gtest.h>

#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>

namespace {

bool fileExists(const std::string& p) { std::ifstream f(p); return f.good(); }

std::string readAll(const std::string& p) {
    std::ifstream f(p);
    std::stringstream ss;
    ss << f.rdbuf();
    return ss.str();
}

std::string clientPath() {
    const char* env = std::getenv("EQ_CLIENT_PATH");
    std::string p = env ? env : EQ_CLIENT_DATA_PATH;
    if (!p.empty() && p.back() != '/') p += '/';
    return p;
}

void runZone(const std::string& zone) {
    const std::string golden = std::string(GOLDEN_DIR) + "/" + zone + ".txt";
    if (!fileExists(golden)) GTEST_SKIP() << "no golden " << golden;
    if (!fileExists(WILLEQ_DB_REAL_PATH)) GTEST_SKIP() << "no shipped db";
    const std::string eq = clientPath();
    if (!fileExists(eq + "global_chr.s3d") || !fileExists(eq + zone + "_chr.s3d"))
        GTEST_SKIP() << "EQ client tree not at " << eq;
    const std::string out = std::string(P_tmpdir) + "/model_fingerprint_" + zone + "_" + std::to_string(::getpid()) + ".txt";
    const std::string cmd = std::string(MODEL_FINGERPRINT_BIN) + " --zone " + zone + " --eq " + eq
                          + " --db " + WILLEQ_DB_REAL_PATH + " --out " + out + " >/dev/null 2>&1";
    const int rc = std::system(cmd.c_str());
    ASSERT_EQ(rc, 0) << cmd;
    const std::string got = readAll(out);
    const std::string want = readAll(golden);
    std::remove(out.c_str());
    if (got != want) {
        // Name the first differing line so the failure is actionable.
        std::istringstream a(got), b(want);
        std::string la, lb;
        int line = 0;
        while (true) {
            const bool ha = static_cast<bool>(std::getline(a, la));
            const bool hb = static_cast<bool>(std::getline(b, lb));
            ++line;
            if (!ha && !hb) break;
            if (la != lb) {
                FAIL() << zone << ": fingerprint differs from the golden at line " << line
                       << "\n  golden: " << lb << "\n  got:    " << la;
            }
        }
        FAIL() << zone << ": fingerprint differs from the golden (same lines, different bytes?)";
    }
}

}  // namespace

TEST(EntitySourcePruning, GfaydarkModelDataIsByteIdenticalToTheGolden) { runZone("gfaydark"); }
TEST(EntitySourcePruning, DreadlandsModelDataIsByteIdenticalToTheGolden) { runZone("dreadlands"); }
TEST(EntitySourcePruning, IcecladModelDataIsByteIdenticalToTheGolden) { runZone("iceclad"); }
TEST(EntitySourcePruning, Qeynos2ModelDataIsByteIdenticalToTheGolden) { runZone("qeynos2"); }
